/// Votes per class, one per tree (nested `if`s).
pub fn forward_inline(x: &[InputType; NUM_FEATURES]) -> [i32; NUM_OUTPUTS] {
    let mut votes = [0; NUM_OUTPUTS];
    vote(&mut votes, tree_0(x));
    vote(&mut votes, tree_1(x));
    vote(&mut votes, tree_2(x));
    vote(&mut votes, tree_3(x));
    vote(&mut votes, tree_4(x));
    vote(&mut votes, tree_5(x));
    vote(&mut votes, tree_6(x));
    vote(&mut votes, tree_7(x));
    vote(&mut votes, tree_8(x));
    vote(&mut votes, tree_9(x));
    vote(&mut votes, tree_10(x));
    vote(&mut votes, tree_11(x));
    vote(&mut votes, tree_12(x));
    vote(&mut votes, tree_13(x));
    vote(&mut votes, tree_14(x));
    votes
}

