/// Predicted class index: most votes, ties to the lowest class.
pub fn predict(x: &[InputType; NUM_FEATURES]) -> usize {
    argmax(&forward(x))
}

/// Predicted class index: most votes, ties to the lowest class.
pub fn predict_inline(x: &[InputType; NUM_FEATURES]) -> usize {
    argmax(&forward_inline(x))
}

